start.sh:
#!/bin/sh
set -eu
cd "$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"
test -x build-906/strata || { echo "Strata binary is missing; see logs/build.log" >&2; exit 1; }
test -f runtime/mtp/dense.txt || { echo "MTP runtime is not ready" >&2; exit 1; }
test -f runtime/Qwen3.8-Flash-Next-GSQ-RCO-IQ1_M/native_experts.txt || { echo "Model pack is not ready" >&2; exit 1; }
if docker container inspect llama-server >/dev/null 2>&1; then
  docker update --restart=no llama-server >/dev/null
  docker stop -t 120 llama-server >/dev/null
fi
docker compose --env-file /home/radneon/llama/.env -f compose.yaml up -d
printf '\nStrata API: 0.0.0.0:8080; startup at system boot enabled via Docker restart policy\nLogs: %s/logs.sh --follow\n' "$PWD"

logs.sh:
#!/bin/sh
set -eu
cd "$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"
case "${1:-}" in
 --follow|-f) exec docker logs --timestamps --tail 200 --follow strata-api ;;
 --build) file=logs/build.log ;;
 --pack) file=logs/pack.log ;;
 --mtp) file=logs/mtp-prepare.log ;;
 "") file= ;;
 *) echo "Usage: $0 [--follow|--build|--pack|--mtp]" >&2; exit 2 ;;
esac
if [ -z "$file" ] && ! docker container inspect strata-api >/dev/null 2>&1; then file=logs/service-last.log; fi
if [ -n "$file" ]; then
 if command -v less >/dev/null 2>&1 && [ -t 1 ]; then exec less +G "$file"; fi
 exec cat "$file"
fi
if command -v less >/dev/null 2>&1 && [ -t 1 ]; then
 docker logs --timestamps strata-api 2>&1 | less +G
else
 docker logs --timestamps strata-api 2>&1
fi
